 43	// TODO: Make these configurable by flags
 44	const (
 45		// DeferredResizeUpdateTimeout defines the duration during which an in-place resize request
 46		// is considered deferred. If the resize is not completed within this time, it falls back to eviction.
 47		DeferredResizeUpdateTimeout = 5 * time.Minute
 48	
 49		// InProgressResizeUpdateTimeout defines the duration during which an in-place resize request
 50		// is considered in progress. If the resize is not completed within this time, it falls back to eviction.
 51		InProgressResizeUpdateTimeout = 1 * time.Hour
