 54	// PodsInPlaceRestriction controls pods in-place updates. It ensures that we will not update too
 55	// many pods from one replica set. For a replica set, it will allow updating one pod or more if
 56	// inPlaceToleranceFraction is configured.
 57	type PodsInPlaceRestriction interface {
 58		// InPlaceUpdate attempts to actuate the in-place resize for the given pod.
 59		// Returns error if the client operation fails.
 60		InPlaceUpdate(pod *corev1.Pod, vpa *vpa_types.VerticalPodAutoscaler, eventRecorder record.EventRecorder) error
 61	
 62		// CanInPlaceUpdate checks if a pod can be safely updated in-place.
 63		// Returns:
 64		//   - InPlaceApproved: The pod can be updated in-place immediately.
 65		//   - InPlaceDeferred: The update should be deferred (e.g., pod is pending, already updating, or group is not disruptable).
 66		//   - InPlaceEvict: The pod should be evicted instead of updated in-place.
 67		//   - InPlaceInfeasible: The in-place update is infeasible (node can't accommodate it or error occurred). Will only retry when recommendation changes.
 68		//
 69		// The updateMode parameter affects the decision:
 70		//   - UpdateModeInPlace: Waits indefinitely for in-progress updates.
 71		//   - UpdateModeInPlaceOrRecreate: May return InPlaceEvict if the pod update exceeds the timeout threshold.
 72		CanInPlaceUpdate(pod *corev1.Pod, vpa *vpa_types.VerticalPodAutoscaler, infeasibleAttempts map[k8stypes.UID]*vpa_types.RecommendedPodResources) utils.InPlaceDecision
 73		// CanUnboost checks if a pod can be safely unboosted.
 74		CanUnboost(pod *corev1.Pod, vpa *vpa_types.VerticalPodAutoscaler) bool
 75	}
