 77	// PodsInPlaceRestrictionImpl is the implementation of the PodsInPlaceRestriction interface.
 78	type PodsInPlaceRestrictionImpl struct {
 79		client                       kube_client.Interface
 80		podToReplicaCreatorMap       map[string]podReplicaCreator
 81		creatorToSingleGroupStatsMap map[podReplicaCreator]singleGroupStats
 82		patchCalculators             []patch.Calculator
 83		clock                        clock.Clock
 84		lastInPlaceAttemptTimeMap    map[string]time.Time
 85		inPlaceSkipDisruptionBudget  bool
 86	}
