 88	// CanInPlaceUpdate checks if pod can be safely updated
 89	func (ip *PodsInPlaceRestrictionImpl) CanInPlaceUpdate(pod *corev1.Pod, vpa *vpa_types.VerticalPodAutoscaler, infeasibleAttempts map[k8stypes.UID]*vpa_types.RecommendedPodResources) utils.InPlaceDecision {
 90		// Use default mode when update mode is nil
 91		updateMode := vpa_types.UpdateModeRecreate
 92		if (vpa.Spec.UpdatePolicy != nil) && (vpa.Spec.UpdatePolicy.UpdateMode != nil) {
 93			updateMode = *vpa.Spec.UpdatePolicy.UpdateMode
 94		}
 95	
 96		if updateMode == vpa_types.UpdateModeInPlace && !features.Enabled(features.InPlace) {
 97			klog.V(4).InfoS("Can't in-place update pod, VPA updateMode is InPlace but InPlace feature gate is not enabled", "pod", klog.KObj(pod), "vpa", klog.KObj(vpa))
 98			return utils.InPlaceDeferred
 99		}
100	
101		cr, present := ip.podToReplicaCreatorMap[getPodID(pod)]
102		if !present {
103			klog.V(4).InfoS("Deferring in-place update because VPA cannot determine whether disrupting this Pod is safe; the Pod may be unmanaged, its controller information may be unavailable, or its replica group may be below the configured minimum size", "pod", klog.KObj(pod))
104			klog.V(5).InfoS("VPA could not add this Pod to a replica group used to enforce availability; the Pod may have no managing controller, its controller may be unavailable, or its group may have fewer replicas than the configured minimum", "pod", klog.KObj(pod), "ownerReferences", pod.OwnerReferences)
105			return utils.InPlaceDeferred
106		}
107	
108		if pod.Status.Phase == corev1.PodPending {
109			klog.V(4).InfoS("Can't in-place update pod, pod is in Pending phase", "pod", klog.KObj(pod))
110			return utils.InPlaceDeferred
111		}
112	
113		singleGroupStats, present := ip.creatorToSingleGroupStatsMap[cr]
114		if !present {
115			klog.V(4).InfoS("Deferring in-place update because VPA has no replica availability information for the Pod's controller and cannot verify that the update is safe", "pod", klog.KObj(pod), "replicaCreator", cr)
116			return utils.InPlaceDeferred
117		}
118	
119		if vpa.Status.Recommendation == nil {
120			klog.V(4).InfoS("Can't in-place update pod, no recommendation available yet. Waiting for next loop", "pod", klog.KObj(pod))
121			return utils.InPlaceDeferred
122		}
123	
124		recommendation := vpa.Status.Recommendation
125	
126		// if the update mode is inPlace we want to check the map for previous Infeasible attempts
127		if updateMode == vpa_types.UpdateModeInPlace && infeasibleAttempts != nil {
128			lastAttempt, exist := infeasibleAttempts[pod.UID]
129			if exist && !resourcehelpers.RecommendationHasLowerResource(lastAttempt, recommendation) {
130				klog.V(2).InfoS("Skipping in-place resize because the previous resize could not be accommodated and the new recommendation does not request fewer resources; VPA will retry after a lower recommendation", "pod", klog.KObj(pod))
131				return utils.InPlaceInfeasibleCached
132			}
133		}
134	
135		resizeStatus := getResizeStatus(pod)
136	
137		// pod is in place updaing
138		// utils.ResizeStatusNone means that  there is no container that is inPodResizePending or PodResizeInProgress state
139		if resizeStatus != utils.ResizeStatusNone {
140			// For InPlace mode: wait for all non-terminal statuses, never evict.
141			// Infeasible attempts are tracked and only retried when recommendation changes.
142			if updateMode == vpa_types.UpdateModeInPlace {
143				switch resizeStatus {
144				case utils.ResizeStatusInfeasible:
145					// Infeasible means node can't accommodate the resize.
146					// Store spec.resources and wait for recommendation to change before retrying.
147					klog.V(4).InfoS("Not retrying in-place resize because the kubelet reported that the node cannot accommodate the requested resources; VPA will retry after the recommendation changes", "pod", klog.KObj(pod))
148					return utils.InPlaceInfeasible
149				case utils.ResizeStatusDeferred:
150					// Deferred means kubelet is waiting to apply the resize.
151					// Do nothing, wait for kubelet to proceed.
152					klog.V(4).InfoS("Deferring in-place update because the kubelet postponed the resize; VPA will wait instead of sending another resize request", "pod", klog.KObj(pod))
153					return utils.InPlaceDeferred
154				case utils.ResizeStatusInProgress:
155					// Resize is actively being applied, wait for completion.
156					klog.V(4).InfoS("In-place update in progress, waiting for completion", "pod", klog.KObj(pod))
157					return utils.InPlaceDeferred
158				case utils.ResizeStatusError:
159					// Error during resize, will retry if recommendation changes.
160					klog.V(4).ErrorS(nil, "Not retrying in-place resize because the kubelet reported an error; VPA will retry only after a recommendation changes", "pod", klog.KObj(pod))
161					return utils.InPlaceInfeasible
162				default:
163					klog.V(4).InfoS("Deferring in-place update because the Pod reports an unrecognized resize status", "pod", klog.KObj(pod), "resizeStatus", resizeStatus)
164					return utils.InPlaceDeferred
165				}
166			}
167	
168			// For InPlaceOrRecreate mode, check timeout
169			canEvict := CanEvictInPlacingPod(pod, singleGroupStats, ip.lastInPlaceAttemptTimeMap, ip.clock)
170			if canEvict {
171				klog.V(5).InfoS("Evicting Pod because its in-place resize has failed or stalled", "pod", klog.KObj(pod), "resizeStatus", resizeStatus)
172				return utils.InPlaceEvict
173			}
174			klog.V(5).InfoS("Deferring update because the Pod already has an in-place resize pending or in progress", "pod", klog.KObj(pod), "resizeStatus", resizeStatus)
175			return utils.InPlaceDeferred
176		}
177	
178		if ip.inPlaceSkipDisruptionBudget {
179			if utils.IsNonDisruptiveResize(pod) {
180				klog.V(5).InfoS("Approving in-place update because the requested resize does not require restarting containers; the configured policy permits this without consuming the replica disruption budget", "pod", klog.KObj(pod))
181				return utils.InPlaceApproved
182			}
183			klog.V(4).InfoS("in-place-skip-disruption-budget enabled, but the Pod has RestartContainer resize policy", "pod", klog.KObj(pod))
184		}
185	
186		if singleGroupStats.isPodDisruptable() {
187			klog.V(5).InfoS("Approving in-place update because the replica group has enough available Pods to maintain its configured availability during the update", "pod", klog.KObj(pod))
188			return utils.InPlaceApproved
189		}
190	
191		klog.V(4).InfoS("Deferring in-place update because resizing this Pod could reduce the replica group below its configured availability; VPA will retry when more replicas are available", "pod", klog.KObj(pod))
192		return utils.InPlaceDeferred
193	}
