195	// CanUnboost checks if a pod can be safely unboosted.
196	func (ip *PodsInPlaceRestrictionImpl) CanUnboost(pod *corev1.Pod, vpa *vpa_types.VerticalPodAutoscaler) bool {
197		if !features.Enabled(features.CPUStartupBoost) {
198			return false
199		}
200		if pod.Status.Phase == corev1.PodPending {
201			return false
202		}
203		expiredAnnotations := vpa_api_util.GetExpiredStartupCPUBoostAnnotations(pod, vpa)
204		if len(expiredAnnotations) == 0 {
205			return false
206		}
207		klog.V(2).InfoS("Pod ready, checking if containers can be unboosted", "pod", klog.KObj(pod))
208		cr, present := ip.podToReplicaCreatorMap[getPodID(pod)]
209		if present {
210			singleGroupStats, present := ip.creatorToSingleGroupStatsMap[cr]
211			if present {
212				if isInPlaceUpdating(pod) {
213					return false
214				}
215				return singleGroupStats.isPodDisruptable()
216			}
217		}
218		return false
219	}
