221	// InPlaceUpdate sends calculates patches and sends resize request to api client. Returns error if client returned error.
222	// Does not check if pod was actually in-place updated after grace period.
223	// CanInPlaceUpdate / CanUnboost should be called first.
224	func (ip *PodsInPlaceRestrictionImpl) InPlaceUpdate(podToUpdate *corev1.Pod, vpa *vpa_types.VerticalPodAutoscaler, eventRecorder record.EventRecorder) error {
225		cr, present := ip.podToReplicaCreatorMap[getPodID(podToUpdate)]
226		if !present {
227			return fmt.Errorf("pod not suitable for in-place update %v: not in replicated pods map", podToUpdate.Name)
228		}
229	
230		// separate patches since we have to patch resize and spec separately
231		resizePatches := []resource_updates.PatchRecord{}
232		annotationPatches := []resource_updates.PatchRecord{}
233		if podToUpdate.Annotations == nil {
234			annotationPatches = append(annotationPatches, patch.GetAddEmptyAnnotationsPatch())
235		}
236		for _, calculator := range ip.patchCalculators {
237			p, err := calculator.CalculatePatches(podToUpdate, vpa)
238			if err != nil {
239				return err
240			}
241			klog.V(4).InfoS("Calculated patches for pod", "pod", klog.KObj(podToUpdate), "patches", p)
242			if calculator.PatchResourceTarget() == patch.Resize {
243				resizePatches = append(resizePatches, p...)
244			} else {
245				annotationPatches = append(annotationPatches, p...)
246			}
247		}
248	
249		if len(resizePatches) == 0 {
250			return errors.New("no resource patches were calculated to apply")
251		}
252	
253		patch, err := json.Marshal(resizePatches)
254		if err != nil {
255			return err
256		}
257	
258		res, err := ip.client.CoreV1().Pods(podToUpdate.Namespace).Patch(context.TODO(), podToUpdate.Name, k8stypes.JSONPatchType, patch, metav1.PatchOptions{}, "resize")
259		if err != nil {
260			return err
261		}
262		klog.V(4).InfoS("In-place patched pod /resize subresource using patches", "pod", klog.KObj(res), "patches", string(patch))
263	
264		if len(annotationPatches) > 0 {
265			patch, err := json.Marshal(annotationPatches)
266			if err != nil {
267				return err
268			}
269			res, err = ip.client.CoreV1().Pods(podToUpdate.Namespace).Patch(context.TODO(), podToUpdate.Name, k8stypes.JSONPatchType, patch, metav1.PatchOptions{})
270			if err != nil {
271				klog.V(4).ErrorS(err, "Failed to patch pod annotations", "pod", klog.KObj(res), "patches", string(patch))
272			} else {
273				klog.V(4).InfoS("Patched pod annotations", "pod", klog.KObj(res), "patches", string(patch))
274			}
275		}
276	
277		eventRecorder.Event(podToUpdate, corev1.EventTypeNormal, "InPlaceResizedByVPA", "Pod was resized in place by VPA Updater.")
278	
279		singleGroupStats, present := ip.creatorToSingleGroupStatsMap[cr]
280		if !present {
281			klog.InfoS("Internal error - cannot find stats for replication group", "pod", klog.KObj(podToUpdate), "podReplicaCreator", cr)
282		} else {
283			singleGroupStats.inPlaceUpdateInitiated = singleGroupStats.inPlaceUpdateInitiated + 1
284			ip.creatorToSingleGroupStatsMap[cr] = singleGroupStats
285		}
286	
287		return nil
288	}
