290	// CanEvictInPlacingPod checks if the pod can be evicted while it is currently in the middle of an in-place update.
291	func CanEvictInPlacingPod(pod *corev1.Pod, singleGroupStats singleGroupStats, lastInPlaceAttemptTimeMap map[string]time.Time, clock clock.Clock) bool {
292		if !isInPlaceUpdating(pod) {
293			return false
294		}
295		lastUpdate, exists := lastInPlaceAttemptTimeMap[getPodID(pod)]
296		if !exists {
297			klog.V(4).InfoS("In-place update in progress for pod but no lastUpdateTime found, setting it to now", "pod", klog.KObj(pod))
298			lastUpdate = clock.Now()
299			lastInPlaceAttemptTimeMap[getPodID(pod)] = lastUpdate
300		}
301	
302		if singleGroupStats.isPodDisruptable() {
303			// if currently inPlaceUpdating, we should only fallback to eviction if the update has failed. i.e: one of the following conditions:
304			// - Infeasible
305			// - Deferred + more than 5 minutes has elapsed since the lastInPlaceUpdateTime
306			// - InProgress + more than 1 hour has elapsed since the lastInPlaceUpdateTime
307			resizePendingCondition, ok := utils.GetPodCondition(pod, corev1.PodResizePending)
308			if ok {
309				switch resizePendingCondition.Reason {
310				case corev1.PodReasonDeferred:
311					if clock.Since(lastUpdate) > DeferredResizeUpdateTimeout {
312						klog.V(4).InfoS(fmt.Sprintf("In-place update deferred for more than %v, falling back to eviction", DeferredResizeUpdateTimeout), "pod", klog.KObj(pod))
313						return true
314					}
315				case corev1.PodReasonInfeasible:
316					klog.V(4).InfoS("In-place update infeasible, falling back to eviction", "pod", klog.KObj(pod))
317					return true
318				default:
319					klog.V(4).InfoS("In-place update condition unknown, falling back to eviction", "pod", klog.KObj(pod), "condition", resizePendingCondition)
320					return true
321				}
322			} else {
323				resizeInProgressCondition, ok := utils.GetPodCondition(pod, corev1.PodResizeInProgress)
324				if ok {
325					if resizeInProgressCondition.Reason == "" && resizeInProgressCondition.Message == "" {
326						if clock.Since(lastUpdate) > InProgressResizeUpdateTimeout {
327							klog.V(4).InfoS(fmt.Sprintf("In-place update in progress for more than %v, falling back to eviction", InProgressResizeUpdateTimeout), "pod", klog.KObj(pod))
328							return true
329						}
330					} else if resizeInProgressCondition.Reason == corev1.PodReasonError {
331						klog.V(4).InfoS("In-place update error, falling back to eviction", "pod", klog.KObj(pod), "message", resizeInProgressCondition.Message)
332						return true
333					} else {
334						klog.V(4).InfoS("In-place update condition unknown, falling back to eviction", "pod", klog.KObj(pod), "condition", resizeInProgressCondition)
335						return true
336					}
337				}
338			}
339			return false
340		}
341		klog.V(4).InfoS("Would be able to evict, but already resizing", "pod", klog.KObj(pod))
342		return false
343	}

